import sys, json
sys.path.insert(0, '/app/categorizationapp')
from categorizationapp import app

client = app.test_client()


def call(bank, acc_type, txns, holder="RAVI KUMAR"):
    payload = {
        "bank": bank, "acc_type": acc_type, "accountUID": "u1",
        "accountHolder": holder, "isPFMEnabled": True,
        "transactions": txns,
    }
    r = client.post('/categorizeTransaction', json=payload)
    assert r.status_code == 200, r.status_code
    return r.get_json()["response"]


def row(desc, typ, amt, remark="", bal=10000.0):
    return {"description": desc, "type": typ, "amount": amt, "remark": remark,
            "balanceAfterTransaction": bal, "transactionDate": "2023-01-01"}


idbi = call("IDBI", "SAVING", [
    row("ACH-BD-NACH-ACME INDUSTRIES", "CREDIT", 50000.0),
    row("GBHDL0123456789 RAVI KUMAR", "CREDIT", 5000.0),
    row("UPI/123456/PAYMENT/ABC", "DEBIT", 100.0),
])
ind = call("INDUSIND", "SAVING", [
    row("TRF TO SOMEONE", "DEBIT", 2500.0, remark="123456"),
    row("NACH MANDATE TOKEN", "CREDIT", 1.0),
    row("POS TXN-SOMESHOP", "CREDIT", 500.0),
    row("VISA POS TXN BIGBAZAAR MUMBAI", "DEBIT", 1200.0),
])
for name, res in (("IDBI", idbi), ("INDUSIND", ind)):
    print("==", name)
    for t in res:
        print(" ", t["description"], "|", t["type"], t["amount"], "->",
              t["transactionCategory"], "/", t.get("transactionSubcategory"),
              "| party:", repr(t.get("partyName")))
